package image_generate

import (
	"fmt"

	"github.com/jonahgcarpenter/oswald-ai/internal/llm"
	"github.com/jonahgcarpenter/oswald-ai/internal/media"
)

// ResultText describes the cached output and request-local model preview.
// Delivery retains the original generated bytes, not the resized preview.
func ResultText(path string, geometry *llm.ImageGeometry, firstFrame bool) string {
	text := "Image generated successfully—you can see it natively now.\nThe latest successful version will be delivered to the user with your final response.\n\nImage: " + path
	if geometry != nil {
		text += fmt.Sprintf("\nSource image: %d×%d.", geometry.SourceWidth, geometry.SourceHeight)
	}
	if firstFrame {
		text += "\n\nNote: Showing only the first frame of this GIF; the original GIF will be delivered."
	}
	return text + media.ImageGeometryNote(geometry)
}
